            [["a" => 1, "b" => [1, "x", null, true, 2.5]], "{'a': 1, 'b': [1, 'x', None, True, 2.5]}"],
            [["k" => ["n" => ["d" => []]]], "{'k': {'n': {'d': []}}}"],
